package cn.zhuatech.testagent.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class TestReleaseCertificationService{public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.requirementsTraceabilityComplete())b.add("需求与测试追溯不完整");if(!r.criticalPathTestsPassed())b.add("关键业务路径测试未通过");if(!r.securityTestsPassed())b.add("安全测试未通过");if(!r.performanceTestsPassed())b.add("性能与容量测试未通过");if(!r.regressionTestsPassed())b.add("回归测试未通过");if(!r.environmentParityVerified())b.add("测试与生产环境一致性未验证");if(r.openReleaseBlockingDefects()>0)b.add("存在未关闭的发布阻断缺陷");if(!r.evidenceArchived())b.add("测试证据未归档");if(!r.finalApprovalComplete())b.add("发布认证审批未完成");if(!b.isEmpty()){a.add("拒绝发布认证并完成测试与缺陷整改");return new Assessment(Decision.BLOCKED,b,a);}if(!r.rollbackTested()||!r.productionMonitoringReady()){if(!r.rollbackTested())a.add("完成发布回滚演练");if(!r.productionMonitoringReady())a.add("配置上线后业务与技术监控");return new Assessment(Decision.CONDITIONAL,b,a);}a.add("签发测试认证并归档范围、环境、结果和审批证据");return new Assessment(Decision.CERTIFY,b,a);}public record Request(@NotBlank String releaseId,boolean requirementsTraceabilityComplete,boolean criticalPathTestsPassed,boolean securityTestsPassed,boolean performanceTestsPassed,boolean regressionTestsPassed,boolean environmentParityVerified,@Min(0)int openReleaseBlockingDefects,boolean evidenceArchived,boolean rollbackTested,boolean productionMonitoringReady,boolean finalApprovalComplete){}public record Assessment(Decision decision,List<String>blockers,List<String>actions){}public enum Decision{CERTIFY,CONDITIONAL,BLOCKED}}
